INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p253896-engl001', 'stk-guest', 'ENGL 001', 'info', '{"desc": "يا شباب ترا كلنا كنا اوريا\n\nخذني انا مثال\nانا جلست بالاوريا سنه ونص خبررره\nوتكينا في الانجلش\nوكنت مسوس مثلك عن الافرج وكم النجاح\nاخر شي قلت اشد حيلي وانشالله الله مايضيع تعبي\nوالحمدلله صبرنا وهذا انا في الجبل\nمعا العلم اني في 002 درجتي في الميجر تحت الافرج بـ 10 درجات\nوجا الفاينل وذاكرت ودعيت الله\nوالحمدلله الله ما ضيع تعبي\nنصييييحه يا اخوي لا تسمع كلام احد\nواهم شي لا تحطم نفسك تفائل بالخير تجده انشالله\nوربنا يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-001/62213/6", "user": "Guest", "ts": 1206053926000, "tid": 62213, "pn": 6}}', 1206053926000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p259035-engl001', 'stk-user2536', 'ENGL 001', 'info', '{"desc": "^^\nشوف يا طويل العمر … ما أبي اخوفك ولا ابي اسهلها عليك …\nالاورال سهل للي ماخذها بأريحية ويدخل على المدرس وهو مروق … وصعب على اللي يدخل على المدرس وهو مرتبك وخايف …\n\nكل ما فيه اعتبر انها سواليف مع مدرس … ولا تدخل وانت مرتبك وخايف لانك ما راح تقدر تتكلم زين …\n\nبالنسبة لدرجتك … في 062 كان معي واحد جدا ممتازة لغته واخذ بالميدتيرم حوالي 87 علما بان افرجنا كان 76 يعني ادفر منكم , المهم الرجال أخذ في الاورال يا 60 يا 65 نسيت بالضبط … علما بانم لغته من افضل طلاب الدفعه لانه ولد في أمريكا ويتكلم بطلاقة … بس شف كيف درجته …🙂\nتعتمد على استعدادك اذا كان جيد ولا لأا … انت سو اللي عليك والباقي على ربك ولا تخاف من الاختبار …\n\nوبالنسبة لدرجته الكلية في الكورس كانت سي 🙂\n\nعلما بانه كان فوووق الافرج ودرجته جدا جدا ممتازة في المديتيرم …\nانتبه لا ترتخي انت … 🙂\n\nوالله يوفقكم …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/engl-001/62213/8", "user": "user2536", "ts": 1207677502000, "tid": 62213, "pn": 8}}', 1207677502000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1277758-engl001', 'stk-user9056', 'ENGL 001', 'info', '{"desc": "ممكن تكتب الآن Essay وتعطيها مدرّسك يوم الأحد في الساعات المكتبية …\nيعلّمك أخطائك ويعطيك نصائح ، وبكذا تستعد شوي للـ Writing …\n\nأمّا بالنسبة للـ Listening فهالمهارة يبيلها وقت وما تتطور بيوم وليله …\nلكن فيه تكنيكات معيّته تُستعمل في أسئلة الـ Listening ، روح لدكتوركم وخلّه يفيدك .\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-test-english-01/151152/3", "user": "user9056", "ts": 1382704554000, "tid": 151152, "pn": 3}}', 1382704554000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p497219-engl001', 'stk-mr.yaser', 'ENGL 001', 'info', '{"desc": "تقدر تشوفها من الموقع\n\nwww.kfupm.edu.sa/pyp\n\nاو حملها على طول من هنا\nEngl 001 - Writing - Reading & Listening\n\nhttp://www.kfupm.edu.sa/pyp/zahid/091/ENGL001_RWL.xls\n\nوالسبيكنق\nhttp://www.kfupm.edu.sa/pyp/zahid/091/SpeakSchedule_AllCourses.xls\n\nدور على الآي دي حقك\nاضغط ctrl +f واكتب رقمك عشان تلاقيه بسرعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80391/2", "user": "Mr.YaSeR", "ts": 1259675634000, "tid": 80391, "pn": 2}}', 1259675634000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p349944-engl001', 'stk-omar_a', 'ENGL 001', 'info', '{"desc": "# WEEK 15\n1English Proficiency Test (EPT): Tuesday, 27 January\n2Writing Exam: Wednesday, 28 January\n\n# WEEK 16\n3Reading Exam: Saturday, 31 January\n4Listening Exam: Sunday, 1 February\n5Speaking Exam: Monday+Tuesday, 2+3 February\n\n1) EPT:\nDuration: 120 min*\nLocation: Bldg 58*\n\n2) WRITING:\nDuration: 90 min*\nLocation: Bldg 58*\n*Questions:\n(1Likes + Dislikes (100 words\n(2Essay-the future (150-200 words\n(3Narrative-pictures (100 words\n\n3) READING:\nDuration: 75 min*\nLocation: Bldg 58*\n*Questions:\n6 1Paragraphs\nIdentify Topic-purpose-\nHeadlines-paragraph match-\nStatement-match & short answers-\n250-300 2words\n-Biography\n\n4) LISTENING:\nDuration: 40 min*\nLocation: Bldg 58*\n*Questions:\n1Sequence of events\n2Attitudes + Feeling\n3Table or Form to complete\n4Short talk\n\n5) SPEAKING:\nDuration: 15 min*\nLocation: Bldg 58*\n*Questions:\n1Personal information\n2Ask for + give study advice\n3Opinions\n\n:For more details\nhttp://www.kfupm.edu.sa/pyp/timetable.xls", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-final-exam-english-001/69348/1", "user": "Omar_A", "ts": 1231441009000, "tid": 69348, "pn": 1}}', 1231441009000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p496590-engl001', 'stk-_aiman', 'ENGL 001', 'info', '{"desc": "English 001 سهل واختباراته اسهل من اختبارات الثانويه العامه بكثير بل مافي مجال تقارنه بينهم\nكانت صدمه لما شفت الاختبار\n\nالريدينق : اختبار بسيط اذكر انه كان اربعه اقسام قسم واحد منهم كان شبه صعب\nاذا ما تغير النظام ما تحتاج تتذكر اي سبيلنق لانه الاسئله غالبيتها اختيارات والجزء الي تحتاج تكتبه تستخرجه من القطعه يعني قدامك الشي الي تنقله\nالتركات خفيفه مثل they haven’t got وفي الصح والخطأ يجيب لكthey have got\nواصلا ما يدققوا على الاخطاء الاملائيه\n\nوالليسنق : ما يحتاج تعب كبير اذا فاهم الي في الكلاس وتقدر تمشي مع الصوتيات الي في الكلاس الاختبار بيجي اسهل منهم وذا ما تغير النظام يعيدون الشريط مرتين و 001 في العاده ماراح تحتاج تسمعه المره الثانيه ههه بس انتبه ما تسرح في الاعاده وتصحى في نص المقطع الي بعده\nحمل الصوتيات وتدرب عليهم اذا مشيت فيهم اكيد بتمشي في الاختبار ان شاء الله\n\nوالسبيكنق : تعتمد اعتماد كبير على البني آدم الي قدامك والبني ادم + البني آدم الثاني الي بيقيموك انت والبني آدم الي قدامك:s\n\nحاول تتكلم مع المدرس قبل ما يبدء good morning , evning , how are you …etc\n\nتدرب على جمل كثير كبر ما تدخل لا تخلي اول تطبيق لك في الاختبار انت وروميتك قرقروا حتى تمل\nلانه كل ما كنت سريع وصوتك واضح فرصتك انك تاخذ درجه عاليه اكثر بكثير من جودة كلامك باسلوب ضعيف\n\nالكلام يعتمد على الانطلاقه لا تفكر في الغرامر كثير\n\nلا تضيع الاونر عليك 001 الانجليش تقدر تخليك اونر حتى لو كنت مضيع في كل المواد 4 ساعات في اليوم\n\nالفيزيا, الاوريا ما كنت مع المدرس مره ولا كنت فاهم ايش يقول حتى . بس قبل الميجير بأسبوع\nجلست على الملخصات ما تركت نوت الى درسته خاصه ادهم وايمن\n\nأبدء بنوت ادهم شوف المسئله وشوف كيف حلها\n\nاعرف كيف تطلع المعطيات وباقي الشغل على الاله الحاسبه\nخاصه الميجر الثاني اكثره حساب وقوانين احفظهم وخلاص\n\nليت النوت ينفع في الجبل مثل الاوريا:)\n\nنصيحه تمر على جميع الاسئلة في في نوت ابو ادهم وايمن ايامنا اذكر كثير من الافكار تكررت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80357/2", "user": "_aiman", "ts": 1259270536000, "tid": 80357, "pn": 2}}', 1259270536000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p211587-engl001', 'stk-user1091', 'ENGL 001', 'info', '{"desc": "بسم الله\n\nأووووووو والله على بالي إنه انجلش 101\n\nما فرقت يا جماعة بس بالنسبة لل Reading بعض المرات يجيبون قطع طويلة مرة فعلشان كذا لا تتعب نفسك وتضيع الوقت وتقراها كلها\n\nاقرأ رؤوس الأقلام مع الهوامش والأشياء الرئيسية المهمة مثل بداية القطع\n\nمشكلة ال Listening إنه يبيله استماع وفهم جيد للي يقوله المسجل أو اللي يلقي الموضوع\n\nفإذا حققت هالشيئين بإذن الله ما تحصل مشكلة\n\nعلشان كذا الاستماع والفهم الجيد جدا مهمين في أكثر كورسات الجامعة\n\nأما السبيكنج فما لحقت عليه\n\nلأنه كان عندنا برزينتيشن (القاء أمام مجموعة من الطلاب والمدرسين) وهذا يبيله فهم وتجهيز للنقاط اللي تبي تتكلم عنها وطرد لأي شعور بالخوف لأن محد بسويلك شي@2@\n\nوكان عندنا أيضا اختبار oral تتكلم مع مدرس أو مدرسين بدون طلاب وهذه لو تحضر أي سالفة حلوة وتتكلم معهم فيها يكفي\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/exam-engl001/59215/4", "user": "user1091", "ts": 1192974638000, "tid": 59215, "pn": 4}}', 1192974638000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p211595-engl001', 'stk-user1853', 'ENGL 001', 'info', '{"desc": "مدري مناهجكم يقولون انها تغيرت عن 26\n\nبس الزبدة الريدنق اقرا القطع الي بالكتاب عندك وحاول تفهمها … وافهم الفوكاب ومعانيه …\n\nاما الرايتنق … المدرس بيعلمك وش بيجي … عشان تتمرن عليه\n\nبقا اللسن والسبيك … ذاكر الفوكاب الي بالكتاب وانتهينا\n\nوالله يوفقك وتعدي الافرج", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/exam-engl001/59215/5", "user": "user1853", "ts": 1192977844000, "tid": 59215, "pn": 5}}', 1192977844000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p211715-engl001', 'stk-user2728', 'ENGL 001', 'info', '{"desc": "اصعب شيء اليسينينغ\n\nلان زي ما تفضل الاخ فريشمان جزاه الله خير وبين انه يحتاج فهم مع تركيز\n\nولانها بتكون اختيارات\n\nلانه راح يكون على اربع اجزاء في الليسينينغ\n1- يقولك كلمة وتحتار من الاختيارات الاربع ويش اللي قالها ( وهذا يتطلب انك تحفظ السبيلينق والنطق الصحيح للكلمة باللهجة الام = البريطانية )*\n\nانتبه\nال r لا ينطق فيها حرف الراء في البريتيش\nوانما تدغم مع حرف الواو\nوعليه\nيعتقد السامع انه نطق حرف الواو ويقع في الخطاء\nوالمفروض انه يحط في باله انها حرف الr\n\n2- تهتم بالسبيكينغ ولكن بتكون اختياري\n\nوالهدف منها انك تتعلم كيف اساليب المحادثة بالانجليزي ( تذكر بانها تكون اختيار من متعدد )\n\nيعني يعطيك في السؤال\n\nwhy did you miss your class?\nanswer:\n1- I am sorry\n2- please forgive me\n3- I had an accedint , so I waited the policeman, therefore I didn`t come to the class\n4- I don`t solve the home work , so ?I felt fear from you\n\nوانت على ضوء الاربع اختيارات راح تختار افضل واحدة\nوالاحتمال الاقرب راح يكون بين 3 و4\nوانت عندها يبيلك تفهم صيغة كلامة\nوتختار الافضل\n\n3- يقول لك مجاضرة لمدة 5 دقائق\nوانت تسجل الارقام والمواعيد واسامي الاشخاص في جدول\n\nومن ثم تحل اسئلة\nوكل سؤال عليه اربع اختيارات\n\nوالجواب راح يكون مدون في الجدول\n\n4- يعطيك محاضرة طولها 7 دقائق\nوفي اثناء المحاضرة تحل 10 اسئلة وكل سؤال له اربع اختيارات\n\nوالجواب الافضل يكون متعلق بالسؤال المكتوب واللي بيقرب لك اكثر المحاضرة اللي بيقولها*\n\nانتبه ترى لكل سؤال 4 اختيارات\nوراح يذكرها كلها في المحاضرة\n\nفلا تتسرع في اختيار الاجابة\nلان اغلبها محتملة ولكن واحدة هي التي تحتمل الدقة والصحة\n\n(( عشان كذا الاخ هجراوي كان يحط راسه على الطاولة ويغني (ياسعدنا وانتي شوفه شوفي مالي البشاير…) في المحاضرتين الطويلتين ويحط الاختيارات كلها على عامود واحد بعد ما يخلص من هذرته\nيعني احط يا c او b ))\n\n----------------------------------------\n\nالرايتينغ\n\nيعتمد عليك وعلى ما يعلمك اياه مدرسك\n\n--------------\nالريدينغ\n\nراح يكون قطعة من القطع اللي بتكون في الكتاب\n\nوانت ما عليك الا تترجم الكلمات وتحفظها\n\nولا جا الاختبار راح يكون عندك متسع من الوقت فقط للريدينغ\n\nأما اللسينيغ تحتاج سرعة البديهة والتركيز في الاجابه وتدوين الجواب( تنطبق فيها المقولة , الوقت كالسيف فان لم تقطعه قطعك )\n\nالرايتينغ يحتاج انك تحط الافكار الرئيسية في راسك قبيل كتابة الموضوع\n\nومن ثم المعلومات بتجيك وانت تكتب\n\n----------------------------------------------------------------------------------\n\nهجراوي مستواه في الرايتينغ 90% وفي الريدينغ 65% وفي اللسينينغ 45%\nفعشان كذا\nما عديت الاوريا الا بفضل من الله ومن ثم الرايتينغ واختبار الاورال= الشفوي =oral\n\nواسمحوا لي عالاطالة\n\nودعواتكم لاخوانكم الفريشمان\nتراهم يمرون في فترة مياجر عصيبة في الوقت الحالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/exam-engl001/59215/10", "user": "user2728", "ts": 1192999299000, "tid": 59215, "pn": 10}}', 1192999299000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p78344-engl001', 'stk-user896', 'ENGL 001', 'info', '{"desc": "عدنـــــــا!\n\nالسلام عليكم ورحمة الله وبركاته…\n\nالأخوة ما قصروا يا معدن،\n\nلكن بودي أن أضيف بعض النقاط الضرورية جداً:\n\nأولاً:المواد بشكل عام\nأنت ستدرس مادتين رئيسيتبن:\nأ. مادة الإنجليزي: وتسمى بـ Engl 001، وهذه المادة تتفرع إلى خمسة مواد أخرى، وهي:\n1- القواعد: Grammar\n2- الكتابة: Writing\n3- الاستماع: Listining\n4- القراءة: Reading\n\n5- المفردات: Vocabulary\n\nالمواد الأربع الأولى ستدرسها في الحصص مع المدرس،، وصدقني أنا أضمن لك العلامة الممتازة في هذه المواد الأربعة إذا التزمت بالحضور الإيجابي(أنظر ثانياً)\nالمادة الفرعية الخامسة(المفردات) لن يتم تدريسها في الجامعة مع المدرس،، بل عليك أنت أن تدرسها بنفسك في البيت وسيكون هناك اختبار قصير اسبوعي في هذه المادة.\nنصيحتي هنا: أن تدرس هذه المادة بجدية،، وبكل ما تحمله من طاقة،، ولا تؤجل دراستها أبداً أبداً… حتى لو تطلب ذلك منك ما يقارب الثمان ساعات أسبوعياً…\n\nب. مادة الرياضيات:\nوهنا عليك أن تحفظ المصطلحات الرياضية الجديدة عليك أولاً بأول،، ولا تؤجل شيئاً،،\nبعد ذلك يجب عليك أن تحل المسائل وتتعب نفسك في حلها ولا تكتفي بالواجبات التي يعطيك اياها المدرس،،\nأيضاً،، لا تنسى مذكرة مسلماني،، ففيها كل ما تحتاجه…\n\nأخيراً،، إضافة لهاتين المادتين الرئيسيتين هناك مادتان لن تحتاجا منك جهداً كبيراً سوى (الحضوووووووور)…\nالأولى هي الرياضة،، والثانية هي الميكانيكا والرسم الهندسي…\n\nملاحظة: يقال أنه سيتم إضافة مادتي الفيزياء والكيمياء إلى السنة التحضيرية،، فإن حصل ذلك فعليك بالجهد المضاعف أخي العزيز:)…\n\nثانياً:الحضور الإيجابي\nاعلم أن الحضور لوحده لا يكفي، فالكرسي والصبورة والطاولة أيضاً حاضرين معكم في الكلاس…\nلكن إذا بغيت يكون فيه فرق بينك وبين هذه الأشياء،، عليك بالتفاعل مع المدرس،،\n\nإسأله عن أي شيء غاب عن فهمك،، شارك معه حتى لو كانت مشاركتك خطأ، وحتى لو لغتك الإنجليزية تعبانة،،\n\nواعلم أن المدرس هو كنز ثمين يجب عليك استغلاله بأحسن طريقة ممكنة، حتى لا تندم على خسارته لاحقاً\n\nثالثاً:لا حياء في العلم\n\nضع في بالك داااااااااااااائماً ما يلي:\n\nإذا كنت لا تتفاعل ولا تسأل مع المدرس لأنك تخشى من الفشيلة،، فاعلم أن كل من حولك هم مثلك، لا يعرفون شيئاً ولا يسألون خوفاً من الفشيلة،،\n\nباختصار:\nإذا كنت تعتقد أنك غبي،، فاعلم أن باقي الطلاب أكثر غباءاً منك!!\nمع احترامي للجميع:)\n\nرابعاً:تمصلح مع المدرس\n\nإعمل على أن تكون علاقتك بالمدرسين جيدة جداً، لأنهم سيفيدونك كثيراً، وسيعطونك نصائحاً تفيدك في مستقبلك الجامعي،،\n\nخامساً:\nحاول أن تتحاور مع المدرسين خارج أوقات الحصص، فذلك سيقوي لغتك الإنجليزية جيداً…\n\n**سادساً:**ما يحتاج نوصيك باختيار الرفقة الحسنة،، يعني بمعنى آخر،، إعمل علاقة مع الدوافييييييير،، وابتعد عن “الدشّـر” 🙂\n\n**سابعاً:**هذه النصائح كلها “ما تسوى قرش” إذا لم تطبقها…\n\nهذا ما لدي، وقد آتيك لاحقاً بما هو أكثر،\n\nوعذراًعلى الإطالة\nتحياتي لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/48253/7", "user": "user896", "ts": 1122453849000, "tid": 48253, "pn": 7}}', 1122453849000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p969348-engl001', 'stk-wait_me', 'ENGL 001', 'info', '{"desc": "يالغالي أذكر كان معنا واحد راسب بسبب أقل من نسبة لكن ما كلم الإدارة ولكن الترم الصيفي كان في أخطاء في الدرجات واللي باقي له نسبة وحدة خلوه ينجح (وما قالوا للناس إللي يجي ينجح واللي ما يدري يعيد)\nفانصحك حاول تكلم الإدارة أول ما ترجع من الإجازة خاصة إذا كان عندك خطأ في كويز من الكوزات الإسبوعية أو استاذك منقصك في الرايتنق\n\nوادع ربك إنه يكتب لك الخير وين ما كان فوالله ما تدري لعل إعادة المادة تكون خير لك ومحفز لأربع سنوات وبالنسبة لقولك لأمك الله يحفظها إنك نجحت فإذا كنت من النوع اللي يكتم ويفكر كثير أنصحك إنك تقولها قبل لا تمشي بيوم وشوف حال غيرك تهون , أنا عدت الماث والإنجلش وكان أبوي و أمي وأخواني (=8 نفر)كلهم متحمسين يعرفون درجتي والله كان يسألوني على كل وجبة غير المفطح اللي جابه الوالد عشاني ومع ذلك قلت لهم قبل لا أسافر إني عدت الماث وبالقوه طلعت وما قدرت أقولهم عن الإنجلش إلا لما وصلت الجامعة بيومين ، وأما إن كنت من نوع آخر فسوي اللي راح يريحك وما يأثر عليك في السمستر الثاني", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001a-69/118296/15", "user": "wait_me", "ts": 1326756949000, "tid": 118296, "pn": 15}}', 1326756949000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p423360-engl001', 'stk-_6_6_6_07', 'ENGL 001', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nبدخل بالموضوع على طول\n\nالحين باقي لي درجتين واعدي انقلش 001 والمشكلة كلها اني انا اصلا ناجح في المادة بس فيه خطأ في الرصد .\n\nلان المدرس سألته عن الكلاس وورك وقالي 75 وانا بنفسي شايف الورقة حقت قريدات الكلاس كامل وبعد شفت درجة السبيكنق عنده وكانت 75 بعد ومكتوب فيها كل درجات الكلاس في الاسبيكنق\n\nالمهم انا لما طلعت نتيجة الانقلش تفاجأت ان الكلاس وورك 63 يعني نازل 12 نسبة\n\nوبعد درجة الاسبيكنق 62.5 يعني نازله 12.5\n\nيعني النسبة النازلة علي 24.5\n\nوالمشكلة بعد ان درجة الرايتنق نفس درجة الميدتيرم وتخيلوا بعد بالفاصلة وكانت 56.67 ونفس الشي في الفاينل يعني مستحيل وبعد نفس الشي الريدنق نفس نسبة المدتيرم وتخيلولوا بالفاصلة بعد .\n((((((((((((((((( مستحيل والله مستحيل ))))))))))))))))))))\n\nالمهم انا سافرت لهلي قبل ما تنزل الدرجة يوم السبت الساعة 7 الصباح وصلت هناك تقريبا الظهر\n\nتفاجأت بالدرجة وقلت انتظر القريد حتى ينزل واشوف وبعدها طلع d+ المهم رجعت للشرقية وبر بعد والمسافة 1500 كيلوا\n\nووصلت اليوم الظهر رحت لمبني الاوريا ما حصلت احد من المدرسين وحصلت هتان التوفيق وعنده طلاب المهم الطلاب يكلمونه وهو يتركهم ولا يكلمهم ويصرفهم وفي الاخير وقفته انا وطالب ثاني وقلنا ما يصير وش نسوي المهم قال ان الدرجات نازله من يوم الثلاثاء وحنا خليناها لليوم عشان الطلاب ما يرجعوا ويراجعوا درجاتهم وان المدرسين الحين مسافرين كلهم ولا احد يقدر يغير اي درجة ابدا .\n\nوكلمته عن سالفتي ولا رد علي وخرج من مبنى الاوريا وانا الحقه ابيه يقولي وش اسوي ما قال شي حتى اني وصلت الى دريشة سيارته وانا الحقه واناديه وراح وخلاني .\n\nالمهم انه انسان … كثير فيه اسم استاذ\n\nابي\n\nاعرف الحين وش اسوي الحين وانا متأكد ان الدرجات ميه في المية موب درجاتي وش الحل تكفون", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/74762/1", "user": "_6_6_6_07", "ts": 1246285013000, "tid": 74762, "pn": 1}}', 1246285013000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p108426-engl001', 'stk-user1222', 'ENGL 001', 'info', '{"desc": "المثابر أبو خليل 🙂\nهذا نموذج للكلمات في منهج الانجلش 001\nNew Vocabulary:\n\nمدير Principal\nرف Shelf\nإنتاج Product\nيثق بـRely on\nعاجل Urgent\nضباب Fog\nبحيرة Lake\nعاصفة رعديةThunderstorm\nمختبر Laboratory\nعلمي Scientific\nيستقر Locate\nمدار السرطان The tropic of cancer\nمدار الجديThe tropic of Capricorn\nمراسم Ceremony\nمهرجان Festival\nشراع Sail\nبحارSailor\nيخترع Invent\nأدبي Moral\nركوب دراجات Cycling\nطبيب أسنانDentist\nضغط Jam\nمشردAdvisor\nمهمة Assignment\nبانتظامRegularly\nنفع Benefit\nوظيفةEmploy\nكفاءة Qualification\nمطلب Requirement\nعمود Column\nخط عرض Latitude\nخط طولLongitude\nمنتصف النهار Meridian\nمنظر طبيعي Landscape\nكاتب مسرحي Playwright\nمأساةTragedy\nجدول مواعيد Schedule\nمستدعApplicant\nتناقصDecrease\nوحدة قياس Unit of measurement\nاستعراضParade\nالاسطولNavy\nغواصة Submarine\nعلى سبيل المجاملة Out of courtesy\n\nوإذا أردت الاستزادة بقم بزيارة مكتبة جرير واسألهم عن مجموعة كتب skills in english\nreading , writing listening & speaking\nlevel 1 2 & 3\n\nوبالنسبة للماث فلا تخاف لأنك راح تحفظها بالممارسة في الحصة ومافي داعي لطريقة الحفظ والتسميع…\n\nعلما أن مناهج الانجلش الجديدة بخلاف القديمة لا تعتمد على طريقة الحفظ وستجد نفسك بانتها كل ثيم ( وحدة ) تجيد استعمال الكلمات … وحماسك رائع واتمنى لك التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001-002/51494/6", "user": "user1222", "ts": 1154357769000, "tid": 51494, "pn": 6}}', 1154357769000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p171886-engl001', 'stk-walaa0c', 'ENGL 001', 'info', '{"desc": "السلام عليكم ورحمته تعالى وبركاته\n\nحبيت اسأل هل بالامكان اعدي ولا لا بالعلم اني عايد ماث وانجلش 001\n\nالانجلش\n\nالميجر الاول 61 والافرج 70\nالميجر الثاني 73.5 والافرج 69.5\nالكنتنيوسسمنت (class work ) على سبيل المثال 65\nالاورال على سبيل المثال 65\nوالفاينل على سبيل المثال 80 وعلى كلام مدرسنا بيكون الافرج 70\n\nالميجر1 15% الميجر2 20% الـclass work 15% الاورال بيكون تبع الـفاينل 50%\n\nالماث\nالميجر1 6.5 والافرج 9.5\nالميجر2 7 والافرج 9.5\nالميدتيرم 11 والافرج 14\nالـclass work على سبيل المثال 5 من 10 والافرج بيكون 5 (مع اني مشارك ممتاز وجبت 8 هوموركات)\nالفاينل من 25 الى 30 والافرج اتوقع بيكون 20\n\nاذا\nمجموع الافرج 58\nومجموع درجاتي 54.5\n\nوكم كانت الافرجات في ترم 052 001", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/56566/1", "user": "walaa0c", "ts": 1180364066000, "tid": 56566, "pn": 1}}', 1180364066000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1406409-engl001', 'stk-kishmallik', 'ENGL 001', 'info', '{"desc": "سلام عليكم\nانا من دفعة 214 وبديت في 01\nويوم اختبرت اول كويز اخذت تحت الافرج ب 5 درجات واختبرت الميد تيرم وتوقعته انه يكون فوق الآفرج بمراحل جتني الصدمة الكبرى\nتحت الافرج ب 20 درجة\nفقدت الأمل صراحة انا عندي كويز هذا الاسبوع والفاينل بعد اسبوعين.\n\nابغى اسألكم هل يمديني أعدي 01 ولا صعب\nوابغى اعرف كم نسبة الي يرسبون ب 01\n\nوالله فشيلة عاد توني دخلت الجامعة حتى 01 ماعديته\n\nنصايحكم تكفووووونن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166411/1", "user": "kishmallik", "ts": 1413820747000, "tid": 166411, "pn": 1}}', 1413820747000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1406515-engl001', 'stk-the_special_one1', 'ENGL 001', 'info', '{"desc": "الفاينل عليه 40 %\nالتيست الجاي 10 % تقريباً\n+\nدرجات اختبار السبيكنق والهومورك ،\n\nحسابياً … مازالت عندك فرصة ، المهم إنك تثق بنفسك وتشد حيلك\nشوف وين نقاط ضعفك في الاستماع أو القراءة أو الفوكاب والقرامر،\nوحاول تركز على المهارة الضعيف فيها … وفالك النجاح ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166411/5", "user": "The_Special_One1", "ts": 1413858119000, "tid": 166411, "pn": 5}}', 1413858119000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p486127-engl001', 'stk-moataz', 'ENGL 001', 'info', '{"desc": "انت راح تكتب عن شخص ما ، وعن اجازة ما ايضاً … وتفاصيل المواضيع غير معلومة الان … في ورقة الاختبار تجدها\n\nوعموما انت تقدر تتدرب على الكتابة، ابدا باساسيات الكتابة … وتعلم كيفية توزيع القطع …\nثم ركز بعدها على المفردات واللغة (الجرامر ) بشكل عام …\n\nيعني هم راح يعطوك معلومات اساسية … وانت عليك انك تستخدمها في تحديد الافكار الاساسية …\nيعني معظم الموضوع راح يكون من راسك … فقط الافكار الاساسية تلقاها في الورقة\n\nطبعاً مدرسنا ذكر لنا الامور اللي يتم الاعتماد عليها في التصحيح وهي ثلاثة :\n\n1- طول الموضوع ( امر مهم جداً ان تكتب موضوع فيه كلمات حسب المطلوب … ماتكون اقل ) - ( 5 نقاط )\n2- المنطقية في سرد الموضوع … يعني مو بس تكتب كلمات وجمل بدون مايكون لها معنى … - ( 5 نقاط )\n3- اللغة اللي تستخدمها ( مستوى المفردات - مستوى القواعد - الهجاء … الخ ) - 5 نقاط\n\nهذي الامور اللي ركز عليها مدرسنا … وقال انها تهم المدرسين وقت التصحيح …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-writing-in-english-001/79684/4", "user": "Moataz", "ts": 1257281249000, "tid": 79684, "pn": 4}}', 1257281249000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p486262-engl001', 'stk-na_f', 'ENGL 001', 'info', '{"desc": "أو أنني أضبط لي\nموضوع وأحفظه في البيت\n\nانه مآ ينكبك الآ هالحركآت …\nيآخي انت مستصعب الانجلش ليه !\nوش فيهآ لو حفظت لك كم فوكآب !!\nيآخي الانجلش مآ يتطور معك الآبالممآرسه تقولي احفظ انس انك تحفظ انقلش وقوآعدهآ\nانشب للمدرس سولف معه بالحصه بعد الكلآس خذ من وقته دقيقتين سوآليف موب كآرشك\n\nملاحظة : موضوعي طرحته وذلك بسبب العقده الموجود عند الأوريا خصوصاً في الرايتنق\n\nلا والله موب عقده الا انت معقدهآ بالغصب !!\nانآ دآخل والانجلش عندي زيرووووووووووووو تربيع مكعب !\nبس الحمد لله طلعت بقريد كويس ب 001 و 002\nدآمك تقول باحفظ قطع بالبيت واجي بالاختبآر\nترآك منت مآشي بالانجلش بالجبل !!\nطلعت عيوني من كثر الكويزآت والتآسكآت وكل تآسك يقول الزود عندي ( كأني مدير شركه )\nنصيحه وانتعقلك برآسك تعرف خلآصك\nيآ مآ نآس حفروا بالاوريآ بسبة الانجلش والسبب الوحيد انهم هم اللي عقدوهآ لانفسهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/the-writing-in-english-001/79684/5", "user": "NA_F", "ts": 1257299535000, "tid": 79684, "pn": 5}}', 1257299535000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p881639-engl001', 'stk-bin_saeed', 'ENGL 001', 'info', '{"desc": "الاختبار هو اختبار توفل … ومن اسمه توفل والاختبار شوي طويل ومو سهل ابد\n\nوبما انك اخذت دورات في الخارج نعم يمديك تعديه وبنسبه كبيره\n\nوالدرجه المطلوبه عشان تعديه وتحذف انجلش 001 فوق 450\n\nوعشان تعدي انجلش 001 و 002 … فوق 500\n\nوقد تختلف حسب اداره الانجلش\n\nوالاختبار عموما من 700 درجه او 800 ماني متاكد كم بالظبط\n\nوراح تحذف عنك الماده فقط وانتهينا وماتتسجلك\n\nعلى العموم اذا عديت فراح تريح … واذا ماعديت ماراح يفرق معك الا الدوام دام ان لغتك ممتازه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/109608/740", "user": "Bin_Saeed", "ts": 1312767883000, "tid": 109608, "pn": 740}}', 1312767883000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1275586-engl001', 'stk-e-asb', 'ENGL 001', 'info', '{"desc": "اول شيء انا دفعت 2012 وح اجاوبك حسب الشيء الي صار معانا السنة الماضية\n\n1 - انا بدأت من 00 وحمدلله خلاص الخمسة المستويات كلها … عمرهم ما جابوا اللسننق او الريدنق من الكتاب … الفاينل كان دايما يجي من بره … فكنت ما ااذاكر القطع الموجودة في الكتاب\n\n2- غالبا المستوى الجديد يبدأ بداية الاسبوع الي بعدو على طول بعد اسبوع الفاينل\n\n3- السبيكينق كان دايما يحددلنا هو المدرس وممكن يختلف من سيكشن لاخرر …يعني شيء يرجع للمدرس نفسوا … في 04 كان كل اخر يوم من الاسبوع فيه سبيكنق وهدا الشيء من الديبارتمنت لكن مدرسنا كان بعض الاحيان يأخروا يوم فيعني السبيكنيق بيد المدرس حقك سواء كدرجات او وقت\n\nبالتوفيق لك 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/150912/2", "user": "e-asb", "ts": 1382201570000, "tid": 150912, "pn": 2}}', 1382201570000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1038450-engl001', 'stk-the_silver', 'ENGL 001', 'info', '{"desc": "^^\n\nالنظام الجديد هو انه في خمسة كورسات للانجليزي بدل من كورسين\nكل كورس مدته 8 اسابيع وتمتحن عليه وتخش في الكورس اللي بعده\nاذا اخذت a او a+ في كورس معين اعتقد تقدر تتجاوز المستوى التالي\nبعض الكتب المستخدمة في النظام الجديد اقوى نوعا ما من النظام الحالي\nالمشكلة اللي سببت انزعاج اغلب الطلاب انه في الكورس الخامس في توفل ولازم تجيب اعلى من 75 عشان تعدي الكورس ولو ما جبتها بترسب في الكورس … بالاضافة انه في كتابة مع استماع مرة وحدة (تستمع لمقطع معين وتلقط منه رؤوس اقلام وتكتب عنها) … بالنسبة للنظام الحالي التوفل كله عليه 10% من الكورس بشرط تجيب درجة بين 400 - 500 درجة … والكتابة بتكون عادية بدون استماع في نفس الوقت\nالحين الخبر المؤكد انه النظام تم الغاؤه على طلاب 211 حتى اللي بيعيدون في السنة الجاية\nبالنسبة لطلاب 212 سمعت انه بيطبق عليهم النظام الجديد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/125066/19", "user": "THE_SILVER", "ts": 1337181197000, "tid": 125066, "pn": 19}}', 1337181197000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1293488-engl001', 'stk-user8598', 'ENGL 001', 'info', '{"desc": "ما قصروا الشباب معكم\nوترى ما في شي صعب بس يبي لك تبذل جهد\n\nانا كان لي موقف في الانقلش 001 كان فيه براكتس قبل الميدترم تدري وش كتب لي المدرس\n\nكتب you will not pass\n\nانواع التحطيم كان وبعدها الميدترم تحت الافرج وخلاص كنت ناوي اسحب بس انتظر ينتهي الترم\n\nوالحمد لله بتوفيق منه شوية جهد ومذاكرة وعديت 001 بفرق درجة\n\nوبعدها عديت 002 والان الحمد لله كوأب والترم الجاي اخر ترم ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/152892/19", "user": "user8598", "ts": 1385324423000, "tid": 152892, "pn": 19}}', 1385324423000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p491653-engl001', 'stk-sub_ze_0_ro', 'ENGL 001', 'info', '{"desc": "الاختبارات طول الله في عمرك 4 اختبارات\n1:سبيكنق وهو يكون في مبنى الاوريا وطريقته انك تجي وقدامك طالب وورقتين انت تاخذ ورقه وخويك ورقه\nوتسوي اللي مطلوب فيها\n\n2:رايتنق في مبنى الاوريا توصف عطله رحت لها وتستخدم الكلمات اللي يدقق عليها المدرس في الكلاس\n\n3:ريدنق اخس اختبار لك ساعه وحده بس تقرا وتحل يعطيك قطعه وتحل الاسئله عليها\n\n4:ليسننق وهو سهل جدا جدا وفيه 10 دقايق اضافيه تنقل فيها اللي كتبته في ورقه الاسئله\nوتحطه في ورقه الاجابه على عكس الريدنق اللي مافيه ولا وقت بدل ضائع\n\nوموفقييييييييييييييييين يااااااااااااارب ان شاء الله نشوفكم في الجبل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80033/3", "user": "sub_ze_0_ro", "ts": 1257984338000, "tid": 80033, "pn": 3}}', 1257984338000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p491660-engl001', 'stk-hasem-kfupm', 'ENGL 001', 'info', '{"desc": "اخوي المنافس اولا رحم الله خالك بدر وجميع المسلمين\nبالنسبة لاختبار الانقلش لا تشيل همه بصراااحة\nالاختبار سهل >>>اذكر انا كنا نروح على فهمنا بالكلاس بدون لامذاكرة ولاشئ\nلكن اذا فيك تحفظ الفوكاب اللي عندك بالكتاب\nالسبيكنق اهم شئ خلك جرئ مع المدرس ولا تستحي واذا ما فهمت على سؤاله قله يعيده عادي<<اول اختبار ما راح يدققون مرة على الاخطاء\nالرايتنق سو براكتس قد ما تقدر على شان تتعود انك تخلص بسرعة\nاللسيننق حاول انك تسوي براكتس على احد المواقع التعليمية وهي كثيرة\nالريدينق اختباري المفضل بصراحة سهل ونصيحة من اخوك انك تقرا اولا السؤال وبعدين تبحث عن الاجابة\nاخيرا لا يغرك كلامي الطويل السالفة سهالات وايزي\nولا تنسى الدعاء وانك توصي امك وابوك انهم يدعون لك\nوفقنا الله واياكم ونشوفكم السنة القادمة بالجبل …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80033/5", "user": "hasem-kfupm", "ts": 1257986390000, "tid": 80033, "pn": 5}}', 1257986390000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1109754-engl001', 'stk-user9335', 'ENGL 001', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته\nادري انه وقت اجازه ولا احد فاضيلي بس والله اني شايل هم الانجليزي خصوصاً اني جايب العيد في الكويزات كلها تحت الافرج ومجموع درجات الرايتنق 6.3 من 7.5 والسبيكنق 70 من 100\nكونوا معي صريحين ولا احد يجاملني تكفووون\nهل استطيع اذا ذاكرت زين للفاينل اللي يوم الاثنين في اول اسبوع بعد العيد اني اعدي الليفل هذا ولا اريح ومهما سويت ما راح اعدي واشد حيلي مره ثانيه في english 01\n\nساعدوني الله يوفقكم ويجزاكم الجنه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-01/133838/1", "user": "user9335", "ts": 1350681436000, "tid": 133838, "pn": 1}}', 1350681436000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1109774-engl001', 'stk-user8581', 'ENGL 001', 'info', '{"desc": "وعليكم السلام\nاخوي … انت شد حيلك , تذكر ان الفاينل عليه نسبة كبيرة يمكن هي الي تنجحك.\nلا تفكر انك تعيد … حاول انك تسوي الي عليك و اذا تعرف احد من الي معاك في نفس المستوى ودرجاته ممتازة سأله عن طريقة مذاكرته … يمكن ينبهك لأشياء انت كنت غافل عنها في المذاكرة او كنت مهملها . انت سو الي عليك في الفاينل وذاكر وحتى لو لا قدر الله عدت الكورس ما راح تندم وتقول ياليتني ذاكرت ومن هالكلام .\nطبعا انا نفسك اوريا ماعندي فكرة عن الدرجات و نظام الانجلش لكن حبيت اعطيك رايي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-01/133838/3", "user": "user8581", "ts": 1350688630000, "tid": 133838, "pn": 3}}', 1350688630000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1109782-engl001', 'stk-user9405', 'ENGL 001', 'info', '{"desc": "طبعا تعدي بإذن الله لو شديت حيلك بالفاينال…ال writing و ال speaking درجاتك فوق ال average فيعدلوا الكويزات…\nويصير وضعك الحين على أقل تقدير با ل C و يمكن C+ أو يمكن B يعتمد على حسب نسبة كل من الكويزات و ال Speaking و ال Writing و الفاينال من العلامة النهائية طبعا.\n\nذاكر للفاينال وابشر…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-01/133838/4", "user": "user9405", "ts": 1350705746000, "tid": 133838, "pn": 4}}', 1350705746000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1110166-engl001', 'stk-user8914', 'ENGL 001', 'info', '{"desc": "اخوي انا معك في نفس الليفل\nوالحمدلله الكويزات منها فوق التسعين ومنها الكامل\nلكن مافي فرق بيني وبينك الكويزات ماعليها شي كثير\n\nنصيحتي لك\nاول شي\nالكتاب الاصفر في أخره فيه قرمر لكل unit\nقبل ماتبدا في اليونيت ابدا في القرامر\nبعدها افتح الكتاب الاصفر وذاكره\nفيه قطع في نفس الكتاب جاء منها اسأله واجد في الكويزات\nكuse of English\n\nبعدها افتح كتاب التمارين حاول تحل كل التمارين اللي في اليونيت\nلما تحس انك فاهم اليونيت\nادخل الانترنت وابحث عن اختبارات في نفس مواضيع اليونيت\nوهذا واحد من المواقع http://www.tolearnenglish.com/\nجدا جدا مفيد\nيعطيك درجة الافرج للي اختبرو ودرجتك\nونفس الاختبار فيه درس عليه\nكل اللي عليك في خانة البحث في الموقع حط اسم الموضوع اللي في اليونيت\n\n-----------\nوخل عندك حد ادنى من الوحدات لازم تخلصها في اليوم\nمثلا لازم تخلص وحدتين او ثلاث كل يوم\n\nطبعا الاشياء هاذي تسويها بعد ماتخلص كل يونيت\n\nومذاكرة الصباح مافيه اطلق منها 👍\n\nوفالك الa+ ان شاء الله\n\n-----------------\nدعواتكم ناخذ a+ ❤️ ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/english-01/133838/6", "user": "user8914", "ts": 1350923950000, "tid": 133838, "pn": 6}}', 1350923950000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p69596-engl001', 'stk-user782', 'ENGL 001', 'srcU', '{"html": "هذه ورقة قمت بعملها لتلخيص موضوع تصاريف الأفعال، مهمة جداً لطلاب ENGL001 ، آمل منكم الاستفادة منها.<br><br>تم رفعها أيضاً إلى skfupm.org وبانتظار موافقة المشرف عليها.<br><br>تحياتي لكم<br><br>​<span data-fid=\"stk-f69596-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f69596-0": {"name": "031_engl001_abduh.net_verbtenses.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/verb-tenses-engl001/45311/1", "user": "user782", "ts": 1109240432000, "tid": 45311, "pn": 1}}', 1109240432000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3458-engl001', 'stk-user3458', 'ENGL 001', 'doc', '{"docs": [{"id": "stk-dr-f68527", "n": "Dr. John Ross Macleod", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "قبل كل شي هذا أفضل مدرس إنجلش درسني في الجامعة على الإطلاق\n\nدرسني في الأوريا engl 001 في 061\n\nمدرس أخلاقه جدا عالية وفيه طيبة عجيبة ما قد شفتها في باقي المدرسين وكمان هادئ الطباع\nوإلى حد الآن متواصلين معه أنا ومجموعة من طلاب السكشن اللي درسوا معي أيام 061\n\nبس المشكلة إنه ما يدرس إلا في السنة التحضيرية ما يدرس كورسات الجبل…\n\nالتحضير : أيام يحضر وأيام ما يحضر…\nطريقة الشرح : يكتب على السبورة كثير حتى ترسخ المعلومة ،، ويستخدم البروجكتر\nالكويزات : شبه أسبوعية و ما يسوي الكويز الين يتأكد من أن الطلاب ماشين معه تمام وفاهمين اللي يقوله.\nالمياجر : كومون\nالفاينلات: كومون\nالقريد النهائي : A\n\nالصوت : واضح جدا ولغته إنجليزية سكوتلندية ،، يعني الآكسنت ممتع جدا…\nإضافات : دخلت التحضيرية وخبرتي في الرايتينق مش ولا بد ،، وتخرجت من عنده بدرجة 94 في الرايتينق…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p346023-engl001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/macleod-john-ross/68527/2", "user": "user3458", "ts": 1230749928000, "tid": 68527, "pn": 2}}]}', 1230749928000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed.q-engl001', 'stk-majed.q', 'ENGL 001', 'doc', '{"docs": [{"id": "stk-dr-f68529", "n": "Dr. David Harold Moore", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": ".ENGL-01, 151 First Module\n\nالتحضير:\nزي ما قالوا الشباب دقيق جدًا في التحضير.\nأول ما يبدأ كلاسه عندك 59 ثانية فقط تكون فيها خارج الكلاس، إذا كملت دقيقة كاملة من بداية الكلاس راح تاخذ ليت (انتبه توريه ساعة جوالك وتقول له شوف توه الوقت).\n5 ليتات = غياب بدون أي تساهل.\n\nطريقة الشرح:\nطريقة الشرح مبدعة جدًا ومسلية لدرجة أنك ما تشتت انتباهك طوال الـ50 دقيقة كاملة، وما حصلت مدرس في الجامعة يسويها.\nمبدع في القرامر، لدرجة أنه يشرح لك قرامر حق اسبوع خلال 5 دقايق.\n\nالهوموورك:\nراح يضغطكم بالهوموورك غير عن بقية المدرسين، ولازم ما تغلط فيه، ولازم تكتبه بالخط اللي يبيه هو، لدرجة أنك راح تلاحظ أن كل الكلاس نفس الخط 🤠 🤠 🤠 شي غريب!\n\nالقريد النهائي:\nA+ بدون مبالغة\n\nالصوت:\nصوته واضح، ولهجته البريطانية مفهومة ويتكلم بصوت عالي وببطئ لدرجة أني كنت افهمه من خلال اسلوبه وأنا ما أعرف شي في الانجليزي!\n\nإضافات ونصائح:\n- انتبه تستعمل الجوال في كلاسه، وانتبه لا يرن جوالك.\n- في بداية الكلاسات يمكن تقول هذا المدرس مرعب وشديد، لكن أنا اضمن لك أنك راح تستفيد منه بشكل مو طبيعي.\n- لا تخاف إذا شفته معصب عليك ويعطيك نظراته المروعة.\n- أؤكد لك أن أي غلطة تسويها في الانجليزي، ما راح تكررها أبدًا؛ عنده اسلوب يخليك تمتنع عن الغلط.\n- المدرس فلّه وعصبيته مجرد شكل، لكنه في الواقع انسان So funny.\n- المدرس مثقف جدًا ويعرف بعض المصلطحات العربية ، ومستعد يجادلك في اللغة العربية احيانًا. 🤠 🤠\n- بإمكانك تروح للـOffice Hour حتى بعد ما تخلص من كلاسه عشان تستفيد منه.\n- حاول تضبط علاقتك معاه وتلتزم بقوانينه اللي ذكروها الشباب فوق، واللي راح يعلمكم اياها هو.\n- يمكن طوال دراستك بالجامعة كلها، أكثر كلاسات ممتعة راح تكون كلاسات David Moore.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1453569-engl001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moore-david-harold/68529/24", "user": "Majed.Q", "ts": 1468269275000, "tid": 68529, "pn": 24}}]}', 1468269275000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-engl001', 'stk-user4988', 'ENGL 001', 'doc', '{"docs": [{"id": "stk-dr-f68614", "n": "Dr. Ian Davison", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كان يوم أسود يوم نزلت عنده الإنقلش 102 الترم اللي طاف (111) ، كان يوم منيل علينا و على الـ gpa حقي !!\n\nانغريت به لما خلصت عنده الـ 101 و اخذت عنده B مطنش كل الكلام اللي قالوا عنه في الـ 102\nرغم إن دوامه كان زفت لكني قلت نمشيها و نتحمل عشان أخرج بقريد طيب في هذا الكورس الغثيث\nفي الأخير لا أرتحنا في الدوام و لا أخذنا قريد زي الآودام !!!\n\nأنا عارف إني سبق و قيمت هذا الآدمي ، لكني عمري ما حقدت على دكتور بهذا الشكل ، خاصة لما أنا خلصت الـ 214 الآن و أكتشفت إننا كنا ظالميين نفسنا لما قررنا نأخذ الكورس [102] عنده …\n\nقبل ما أكمل بأعطيكم بطاقة درجاتي في كل كورسات الإنقلش على أسلوب أبطال الجيش الحُر - و قولوا ما شاء الله -/\n\nEngl001=B\nEngl002=B\nEngl101=B\nEngl102=C\nEngl214=B\n\nغضوا الطرف على حكاية “الرقم المميز” ، لكن من القريدات يتضح إني طالب جيدجداً في الإنقلش و اللغة ما تشكل لي مشكلة و لله الحمد و المنة !\nأنا أصلاً ما أركز في مذاكرة الكورس لأنه عندي القدرة مسبقاً و أوفر وقت مذاكرتها لكورسات أخرى\nو أنا مو من النوع اللي “أشبك” للدكاترة ، و أعوذ بالله أن أكون من المشبكين\nأسلم اللي علي و أحضر الكلاسات …\nو مع ذلك كله الحمدلله أخرج بقريد طيب سلام سلام !!\n\nنرجع للأخو / والله كنا ننقرف و نسحب رجولنا في العصرية عشان نحضر كلاساته ، أسلم الأسانيمنت أول بأول ،تعبنا في الريبوت و الفاينل و التوفل ، أضطريت أركز على الميد تيرم عشان نطلع بقريد على أساس إنه الترم ذا الرجال أنقلب علينا بشكل غبي\nوين ديفسون الطيب اللي كنا عنده 101 ؟؟ ما أدري ؟؟؟\nو أذكر درجات الميد تيرم ،،، كانت تفشل !!! والله ثلاث أرباع السكشن من f إلى C ، و الشنب عندنا أخذ B\nو أخرتها ؟؟؟؟ حط القريد في الترانكسيبت بدون مراجعة ، بدون ما نعرف كم أخذنا في الريبورت و التوفل و الفاينل ، أرسلنا له لكنه طنش !!\n\nجينا للـ214 ، والله الذي لا إله غيره !!! والله ما أنكرفت و لا أشتغلت نص الشغل اللي سويته في الـ102 ، كنت أحضر الكلاس كل يوم ( زي 102 ) و أسلم اللي علي فقط و خرجت بـB سلام سلام\n\nإيش يعني الكلام هذا ؟؟\nAccording to Josh Billam (2012) :“We will be tough to 102 students when we grade their papers”\nقال لنا الكلام هذا لما وزع علينا درجة الميدتيرم !! و ما أعتقد إنه بيكذب لأني حسيت بهذا الشيء لما كنت أدرس الـ102\n\nبس الديفسون ما شاء الله ،،، ما صدق !!!\nوصلت مواصيله إنه يعطيني F في أحد الهومووركات اللي سلمتها لسبب بايخ ، عشان السبب البايخ ده تقوم تساويني باللي يغيب و اللي ما سلم ؟؟؟ عجيب مخك يا شيخ !!\n\nنصيحة للي يحب نفسه و يحب الـ gpa حقه :\nوخر عنه إذا شفته منزل كورس آخر غير الـ 101 !!!\nلا قريد طيب و لا دوام طيب و لا أخلاق طيبة !!!\n\nأشوفه بينزل 214 السنة الجاية ،، ما أدري عنه كيف بيكون في ذاك الكورس ، بس الحذر واجب !!\nو شف لك مدرس ثاني ،،،\n\nأنا ودي أعرف إيش سوى في طلاب الإنقلش 102 السمستر هذا (112) ، ودي أسمع منهم !!!\n\nو آسف على الإطالة ، لكنها حرقة في بطني و قررت أنفثها هنا كالتنين\n\nو سلامتكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048972-engl001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ian-davison/68614/61", "user": "user4988", "ts": 1338556799000, "tid": 68614, "pn": 61}}]}', 1338556799000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10953-engl001', 'stk-user10953', 'ENGL 001', 'doc', '{"docs": [{"id": "stk-dr-f172424", "n": "Dr. John Baker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني بالاوريا السنه ذي ENGL001\n\nالشرح : الرجال مايقصر والله يحاول بكل الطرق يوصل المعلومه لك ويعطيك افضل ماعنده وعنده وورك شيت كان يوزعها لنا تختبر فهمنا بالgrammer\nمرات شرحه يجيب النوم للامانه و اذا على اخلاقه ماعليها والله طيب\nالتحضير : تحضيره شديد بالعاده مش دائما ينادي بالاسماء بداية كل كلاس لكن ايام المياجر كلمه بالOffice hours وما راح يسجلها لك بس لا تزودها 🤣\nالكويزات : ما فيه\nالمياجر : مافيه\nالفاينل : برضو مافيه\n\nبالنهاية اشوف شرحه من جيد الى ممتاز يعيبه اسلوبه مو ذاك الحماس للاسف وبس .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474846-engl001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-baker/172424/3", "user": "user10953", "ts": 1497047874000, "tid": 172424, "pn": 3}}]}', 1497047874000, 1794835933, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
